            continue
        # All constraints satisfied
        return {
            'big_side': int(S),
            'small_side': int(s),
            'ab_num': int(ab_num),
            'ab_den': int(ab_den)
        }
    # Fallback deterministic values if random attempts fail (should be rare)
    S = 40
