    D = k*k - 4*L*(1 - L)
    if D <= 0:
        # No valid acute rotation yields the given AB
        return (False, None)
    # Require D be a rational square to ensure exact recovery and avoid float shortcuts
    num = D.numerator
    den = D.denominator
    def is_square(n):
        r = int(n**0.5)
        while (r+1)*(r+1) <= n:
            r += 1
        while r*r > n:
            r -= 1
        return r*r == n, r
    ok_num, rnum = is_square(num)
    ok_den, rden = is_square(den)
    if not (ok_num and ok_den):
        # Enforce difficulty: instances must invert exactly via radicals; generator guarantees this
        return (False, None)
    sqrtD = Fraction(rnum, rden)
    # Choose the physically meaningful root (the '+' root gives X in (1, sqrt(2)) for valid instances)
    X = (k + sqrtD) / (2*L)
    if not (X > 1):
        # Wrong branch or invalid instance (should not happen with generator)
        return (False, None)
    # Compute area A = S^2 * [1 - (X - k)^2 / (X^2 - 1)]
    A = Fraction(S*S, 1) * (Fraction(1,1) - ((X - k)*(X - k)) / (X*X - 1))
    # Final answer is m+n for A = m/n in lowest terms
    A_red = A  # Fraction already in lowest terms under exact arithmetic
    m = A_red.numerator
    n = A_red.denominator
    if m <= 0 or n <= 0:
        return (False, None)
    answer = m + n
    return (True, int(answer))


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
